ValidationRule.errorConditionFormula:
AND(
    /* TVM Only */
    Foundation_Record__c = false,

    /* Checks if Case Request is blank */
    ISPICKVAL(Case_Request__c, ""),

    /* Checks if any status picklist is set to 'Closed' */
    OR(
        ISPICKVAL(Status, "Closed"),
        ISPICKVAL(Status_Digital__c, "Closed"),
        ISPICKVAL(Status_General__c, "Closed"),
        ISPICKVAL(Status_Production__c, "Closed"),
        ISPICKVAL(Status_Filtered__c, "Closed"),
        FD_Status__c = "Closed",
        ISPICKVAL(Status_CS__c, "Closed")
    )
)
